insert into public.technique_steps (technique_id, step_number, title, instruction, media_id) values
  ('a1111111-1111-4111-8111-111111111101', 1, '손잡이 잡기', '칼 손잡이를 손바닥 전체로 감싸 안정적으로 잡습니다.', 'd4444444-4444-4444-8444-444444444101'),
  ('a1111111-1111-4111-8111-111111111101', 2, '손가락 위치', '검지와 엄지는 칼날 뒤쪽에 가까이 두되 칼날에 닿지 않게 합니다.', 'd4444444-4444-4444-8444-444444444102'),
  ('a1111111-1111-4111-8111-111111111101', 3, '재료 고정', '다른 손 손가락을 안쪽으로 말아 재료를 잡고 마디로 칼날을 안내합니다.', 'd4444444-4444-4444-8444-444444444103'),
  ('a1111111-1111-4111-8111-111111111102', 1, '고정하기', '재료의 한쪽을 잘라 도마에 닿는 면을 만듭니다.', 'd4444444-4444-4444-8444-444444444201'),
  ('a1111111-1111-4111-8111-111111111102', 2, '껍질 벗기기', '칼날을 껍질 바로 아래에 넣고 손목을 천천히 밀어 벗깁니다.', 'd4444444-4444-4444-8444-444444444202'),
  ('a1111111-1111-4111-8111-111111111102', 3, '확인', '껍질이 두껍게 남았는지 보고 남은 부분만 다시 다듬습니다.', 'd4444444-4444-4444-8444-444444444203'),
  ('a1111111-1111-4111-8111-111111111103', 1, '편썰기', '재료를 일정한 두께의 편으로 먼저 썹니다.', 'd4444444-4444-4444-8444-444444444301'),
  ('a1111111-1111-4111-8111-111111111103', 2, '겹치기', '편을 조금씩 겹친 뒤 가늘게 채를 썹니다.', 'd4444444-4444-4444-8444-444444444302'),
  ('a1111111-1111-4111-8111-111111111103', 3, '고르기', '너무 굵은 채는 한 번 더 나눠 굵기를 맞춥니다.', 'd4444444-4444-4444-8444-444444444303'),
  ('a1111111-1111-4111-8111-111111111104', 1, '모으기', '재료를 도마 가운데로 모아 칼이 닿는 범위를 좁힙니다.', 'd4444444-4444-4444-8444-444444444401'),
  ('a1111111-1111-4111-8111-111111111104', 2, '다지기', '칼끝을 도마에 가볍게 붙인 채 위아래로 움직여 작게 다집니다.', 'd4444444-4444-4444-8444-444444444402'),
  ('a1111111-1111-4111-8111-111111111105', 1, '방향 잡기', '재료를 고정하고 칼날을 같은 방향으로 내려 썹니다.', 'd4444444-4444-4444-8444-444444444501'),
  ('a1111111-1111-4111-8111-111111111105', 2, '두께 유지', '앞 조각의 두께를 기준으로 같은 간격으로 반복합니다.', 'd4444444-4444-4444-8444-444444444502'),
  ('a1111111-1111-4111-8111-111111111106', 1, '팬 올리기', '팬을 중불에 올리고 손등을 가까이 대 온기를 확인합니다.', 'd4444444-4444-4444-8444-444444444601'),
  ('a1111111-1111-4111-8111-111111111106', 2, '기름 두르기', '물방울이 구르듯 움직이면 기름을 두르고 팬을 굴려 펴줍니다.', 'd4444444-4444-4444-8444-444444444602'),
  ('a1111111-1111-4111-8111-111111111107', 1, '순서대로 넣기', '익는 시간이 긴 재료부터 넣고 향신 재료는 나중에 넣습니다.', 'd4444444-4444-4444-8444-444444444701'),
  ('a1111111-1111-4111-8111-111111111107', 2, '빠르게 섞기', '주걱으로 바닥부터 뒤집어 재료가 한곳에 머물지 않게 볶습니다.', 'd4444444-4444-4444-8444-444444444702');
