insert into public.recipes (id, slug, name, description, difficulty, estimated_minutes, servings, required_tools) values
  ('b2222222-2222-4222-8222-222222222201', 'kimchi-fried-rice', '김치볶음밥', '잘게 썬 김치와 밥을 빠르게 볶아 만드는 기본 볶음밥입니다.', 2, 20, 1, array['칼', '도마', '프라이팬', '주걱']),
  ('b2222222-2222-4222-8222-222222222202', 'vegetable-stir-fry', '야채볶음', '채썬 채소와 기본 간장을 넣어 단시간에 볶습니다.', 2, 18, 2, array['칼', '도마', '프라이팬']),
  ('b2222222-2222-4222-8222-222222222203', 'bibim-guksu', '비빔국수', '삶은 소면에 채썬 채소와 양념을 버무립니다.', 2, 25, 2, array['칼', '도마', '냄비']),
  ('b2222222-2222-4222-8222-222222222204', 'stir-fried-udon', '볶음우동', '우동면과 채소를 팬에서 함께 볶는 한 그릇 요리입니다.', 3, 25, 2, array['칼', '도마', '프라이팬', '냄비']),
  ('b2222222-2222-4222-8222-222222222205', 'egg-fried-rice', '계란볶음밥', '스크램블 계란과 밥을 섞어 빠르게 볶습니다.', 1, 15, 1, array['프라이팬', '주걱']),
  ('b2222222-2222-4222-8222-222222222206', 'potato-stir-fry', '감자볶음', '감자를 편 썰어 양파와 함께 볶는 밑반찬입니다.', 2, 20, 2, array['칼', '도마', '프라이팬']),
  ('b2222222-2222-4222-8222-222222222207', 'onion-egg-stir-fry', '양파계란볶음', '얇게 썬 양파와 계란을 부드럽게 볶습니다.', 1, 12, 1, array['칼', '도마', '프라이팬']),
  ('b2222222-2222-4222-8222-222222222208', 'cucumber-salad', '오이무침', '오이를 썰어 간단한 양념에 무칩니다.', 1, 10, 2, array['칼', '도마']),
  ('b2222222-2222-4222-8222-222222222209', 'carrot-stir-fry', '당근채볶음', '가늘게 썬 당근을 참기름 향과 함께 볶습니다.', 2, 15, 2, array['칼', '도마', '프라이팬']),
  ('b2222222-2222-4222-8222-222222222210', 'green-onion-stir-fry', '대파볶음', '어슷 썬 대파를 간장과 함께 볶아 밥반찬으로 씁니다.', 2, 12, 2, array['칼', '도마', '프라이팬']);
