insert into public.recipe_steps (recipe_id, step_number, instruction, technique_id) values
  ('b2222222-2222-4222-8222-222222222201', 1, '김치를 잘게 다지고 대파는 송송 썹니다.', 'a1111111-1111-4111-8111-111111111104'),
  ('b2222222-2222-4222-8222-222222222201', 2, '팬을 예열한 뒤 기름을 두르고 김치를 볶습니다.', 'a1111111-1111-4111-8111-111111111106'),
  ('b2222222-2222-4222-8222-222222222201', 3, '밥을 넣고 김치와 섞이도록 볶습니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222201', 4, '계란을 한쪽으로 밀어 익힌 뒤 참기름을 넣고 마무리합니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222202', 1, '당근, 양파, 파프리카, 양배추를 채 썹니다.', 'a1111111-1111-4111-8111-111111111103'),
  ('b2222222-2222-4222-8222-222222222202', 2, '마늘을 다진 뒤 팬을 예열합니다.', 'a1111111-1111-4111-8111-111111111106'),
  ('b2222222-2222-4222-8222-222222222202', 3, '당근부터 넣고 양파, 양배추, 파프리카 순으로 볶습니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222202', 4, '간장으로 간하고 숨이 죽으면 불을 끕니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222203', 1, '소면을 끓는 물에 삶아 찬물에 헹굽니다.', null),
  ('b2222222-2222-4222-8222-222222222203', 2, '오이와 당근을 가늘게 채 썹니다.', 'a1111111-1111-4111-8111-111111111103'),
  ('b2222222-2222-4222-8222-222222222203', 3, '고추장, 식초, 설탕, 참기름을 섞어 양념을 만듭니다.', 'a1111111-1111-4111-8111-111111111104'),
  ('b2222222-2222-4222-8222-222222222203', 4, '면과 채소, 양념을 버무리고 계란을 올립니다.', null),
  ('b2222222-2222-4222-8222-222222222204', 1, '우동면을 데치고 양파와 당근, 대파를 썹니다.', 'a1111111-1111-4111-8111-111111111103'),
  ('b2222222-2222-4222-8222-222222222204', 2, '팬을 예열하고 마늘과 채소를 볶습니다.', 'a1111111-1111-4111-8111-111111111106'),
  ('b2222222-2222-4222-8222-222222222204', 3, '면을 넣고 간장과 함께 볶아 국물이 배게 합니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222205', 1, '대파를 송송 썰고 계란을 풀어 둡니다.', 'a1111111-1111-4111-8111-111111111104'),
  ('b2222222-2222-4222-8222-222222222205', 2, '팬을 예열한 뒤 계란을 스크램블합니다.', 'a1111111-1111-4111-8111-111111111106'),
  ('b2222222-2222-4222-8222-222222222205', 3, '밥을 넣고 간장으로 간하며 볶습니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222206', 1, '감자 껍질을 벗기고 얇게 썹니다.', 'a1111111-1111-4111-8111-111111111102'),
  ('b2222222-2222-4222-8222-222222222206', 2, '양파와 당근도 비슷한 크기로 썹니다.', 'a1111111-1111-4111-8111-111111111105'),
  ('b2222222-2222-4222-8222-222222222206', 3, '팬을 예열하고 감자가 투명해질 때까지 볶은 뒤 양파를 더합니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222207', 1, '양파를 얇게 썹니다.', 'a1111111-1111-4111-8111-111111111105'),
  ('b2222222-2222-4222-8222-222222222207', 2, '팬을 예열하고 양파를 투명해질 때까지 볶습니다.', 'a1111111-1111-4111-8111-111111111106'),
  ('b2222222-2222-4222-8222-222222222207', 3, '푼 계란을 넣고 부드럽게 섞으며 익힙니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222208', 1, '오이를 어슷 썰고 대파는 송송 썹니다.', 'a1111111-1111-4111-8111-111111111105'),
  ('b2222222-2222-4222-8222-222222222208', 2, '고춧가루, 식초, 설탕, 참기름, 소금을 섞어 무칩니다.', null),
  ('b2222222-2222-4222-8222-222222222209', 1, '당근 껍질을 벗기고 가늘게 채 썹니다.', 'a1111111-1111-4111-8111-111111111103'),
  ('b2222222-2222-4222-8222-222222222209', 2, '팬을 예열하고 당근이 부드러워질 때까지 볶습니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222209', 3, '소금과 참기름, 깨로 마무리합니다.', null),
  ('b2222222-2222-4222-8222-222222222210', 1, '대파를 어슷하게 썹니다.', 'a1111111-1111-4111-8111-111111111105'),
  ('b2222222-2222-4222-8222-222222222210', 2, '팬을 예열하고 대파를 볶아 단맛을 냅니다.', 'a1111111-1111-4111-8111-111111111107'),
  ('b2222222-2222-4222-8222-222222222210', 3, '간장과 설탕, 참기름을 넣고 섞습니다.', 'a1111111-1111-4111-8111-111111111107');
